/**
 * Worker entry point (ADR-5): the OpenNext worker plus a Cron `scheduled`
 * handler that runs the Instagram webhook retry sweep.
 *
 * `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
 */
// @ts-ignore -- generated at build time, no type declarations
import { default as handler } from "./.open-next/worker.js";
import { runScheduledSweep, type ScheduledSweepEnv } from "./src/lib/runtime/scheduledSweep";

interface ExecutionContextLike {
  waitUntil(promise: Promise<unknown>): void;
}

const openNextHandler = handler as {
  fetch(request: Request, env: unknown, ctx: ExecutionContextLike): Promise<Response>;
};

const worker = {
  fetch: openNextHandler.fetch,

  async scheduled(_event: unknown, env: ScheduledSweepEnv, ctx: ExecutionContextLike) {
    ctx.waitUntil(runScheduledSweep(openNextHandler.fetch, env, ctx));
  },
};

export default worker;

// Durable Objects declared by the OpenNext build must be exported from the entry.
// @ts-ignore -- generated at build time, no type declarations
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
